"""Rules are BRANCHES, not sentences. Deterministic, testable, free.
The model is used ONLY to compose the final reply."""
from rafeeq.core.config import AUTO_REFUND_LIMIT_SAR, REFUND_LIMIT_SAR

class RefundState(TypedDict, total=False):
    order_id: str
    amount: float | None
    sla_breached: bool | None
    already_refunded: bool | None
    decision: Literal["auto_approve", "approve", "needs_human", "reject", None]

def eligibility_gate(state: RefundState) -> Literal["reject", "decide"]:
    if state.get("already_refunded"):     # rule -> branch (no model)
        return "reject"                   # never refund twice
    if not state.get("sla_breached"):
        return "reject"                   # not eligible
    return "decide"

def amount_gate(state: RefundState) -> Literal["auto_approve", "approve", "needs_human"]:
    # THE rule a prompt could not guarantee — now uncrossable structure.
    amount = state.get("amount") or 0.0
    if amount <= AUTO_REFUND_LIMIT_SAR:
        return "auto_approve"             # <= 50 SAR, fully autonomous
    if amount <= REFUND_LIMIT_SAR:
        return "approve"                  # <= 500 SAR, policy-controlled
    return "needs_human"                  # > 500 SAR, human approval

"""Business rules are now PURE FUNCTIONS — table-tested, no model.
This is the payoff a prompt can never give you."""

@pytest.mark.parametrize("amount, expected", [
    (0.01, "auto_approve"),
    (AUTO_REFUND_LIMIT_SAR, "auto_approve"),          # boundary: 50 -> auto
    (AUTO_REFUND_LIMIT_SAR + 0.01, "approve"),         # just above -> policy
    (REFUND_LIMIT_SAR, "approve"),                     # boundary: 500 -> ok
    (REFUND_LIMIT_SAR + 0.01, "needs_human"),          # just above -> human
    (5000.0, "needs_human"),
])
def test_amount_gate(amount, expected):
    assert amount_gate({"amount": amount}) == expected  # same input, same route

@pytest.mark.parametrize("refunded, sla, expected", [
    (True,  True,  "reject"),      # never twice, wins regardless of SLA
    (False, False, "reject"),      # not eligible
    (False, True,  "decide"),      # eligible -> decide amount
])
def test_eligibility_gate(refunded, sla, expected):
    assert eligibility_gate({"already_refunded": refunded, "sla_breached": sla}) == expected

"""THE LAST LINE, and the MOST RELIABLE — it inspects the CONCRETE
tool call about to happen, not predicted intent. Blocks an over-limit
refund even if input_guard missed the injection that produced it."""
def guard_tool_call(tool_name, args, actor_customer_id=None):
    decision = classify(tool_name, args)          # the action-risk matrix

    if decision.prohibited:
        log_security_event("blocked_prohibited_action", args, "critical")
        return {"error": "prohibited_action"}

    if decision.requires_human_approval:
        log_security_event("blocked_over_limit_refund", args, "high")
        return {"error": "refund_over_limit_requires_human_approval"}

    # structuring fix: several under-limit calls on the SAME order can
    # sum past REFUND_LIMIT_SAR even if each call alone looks fine.
    if tool_name == "issue_refund":
        cumulative = _already_refunded(args["order_id"]) + args["amount"]
        if cumulative > REFUND_LIMIT_SAR:
            return {"error": "cumulative_refund_over_limit_requires_human_approval"}

    return None   # allow — call proceeds unchanged
